<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit;
require dirname(__DIR__).'/app/bootstrap.php';
$db=fb_db();if($db->query('SELECT DATABASE()')->fetchColumn()!=='axioma_furto_roubo')throw new RuntimeException('Os testes locais exigem o banco independente de desenvolvimento.');
$checks=0;function check($value,string $message):void{global $checks;if(!$value)throw new RuntimeException($message);$checks++;}
$source=$argv[1]??'C:/Users/admin/Downloads/11 AANESC.xlsx';$parsed=Spreadsheets::read($source,basename($source));check(count($parsed['rows'])===474,'474 linhas úteis');check(count($parsed['errors'])===0,'Sem linhas rejeitadas');$plan=Spreadsheets::plan($db,$parsed,hash_file('sha256',$source));check($plan['skipped']===474,'Reimportação identificada');
$stats=Records::stats($db);check($stats['total']===474,'Total preservado');check($stats['furtos']===82&&$stats['roubos']===2,'Tipos informados preservados');check($stats['sem_data']===5,'Datas ambíguas não inventadas');
check(Records::date('29/02/2028')==='2028-02-29','Ano bissexto');check(Records::date('31/02/2026')===null,'Data impossível');check(Records::date('07/03/20025')===null,'Ano inválido');check(Records::date('20 A 21/05/2026')===null,'Intervalo preservado');
try{Records::where(['q'=>['invalido']]);throw new RuntimeException('Filtro inválido aceito');}catch(InvalidArgumentException $e){$checks++;}
$records=Records::list($db,[],50000)['rows'];foreach(['xlsx','csv'] as $format){$file=tempnam(sys_get_temp_dir(),'fb_roundtrip_');try{Spreadsheets::export($records,$format,$file);$again=Spreadsheets::read($file,'teste.'.$format);check(count($again['rows'])===474,'Roundtrip '.$format);check(count($again['errors'])===0,'Linhas válidas '.$format);$update=Spreadsheets::plan($db,$again,hash_file('sha256',$file));check($update['updates']===474,'IDs reconhecidos '.$format);check(count(array_filter($again['rows'],static fn($r)=>$r['data']['data_evento']===null))===5,'Datas mantidas '.$format);}finally{unlink($file);}}
$db->beginTransaction();try{$data=['placa'=>'ZZZ0Z98','veiculo'=>'Teste transacional','evento'=>'Roubo','data_evento'=>'2026-10-16','municipio'=>'JOINVILLE/SC','etapa'=>'Em buscas'];$r=Records::save($db,$data,1);check($r['revision']===1,'Revisão inicial');$data['etapa']='Recuperado';$data['situacao']='Recuperado';$r2=Records::save($db,$data,1,(int)$r['id'],1);check($r2['revision']===2,'Revisão de edição');check(count(Records::history($db,(int)$r['id']))===2,'Histórico de criação e edição');try{Records::save($db,$data,1,(int)$r['id'],1);throw new RuntimeException('Revisão antiga aceita');}catch(UnexpectedValueException $e){$checks++;}check(Records::list($db,['q'=>'ZZZ-0Z98'])['total']===1,'Busca de placa com hífen');check(Records::list($db,['q'=>"' OR 1=1 --"])['total']===0,'Busca parametrizada');}finally{$db->rollBack();}
check(Records::stats($db)['total']===474,'Teste não deixou registros');$filters=Assistant::filters($db,'Quantos furtos em Joinville em 2026?',[]);check($filters['evento']==='Furto'&&$filters['municipio']==='JOINVILLE/SC'&&$filters['inicio']==='2026-01-01','Filtros de linguagem natural');check(Records::list($db,Assistant::filters($db,'Quais ocorrências estão em aberto?',[]))['total']===437,'Registros em acompanhamento');
echo $checks," verificações de importação, exportação, datas, IDs, histórico, revisão, filtros e isolamento aprovadas.\n";
